// ===== File: tentaflow-codec-core/src/schema.rs — static description of the protocol wire types =====
//
// Generated by build.rs from the protocol sources. One table serves both
// directions: the decoder needs to tell structs from user-data maps, the encoder
// needs the scalar kind, bytes and requiredness of every field.

#[derive(Clone, Copy)]
pub(crate) enum Ty {
    Str,
    Bool,
    /// A unit struct: `null` on the wire.
    Unit,
    Uint(u8),
    Sint(u8),
    Float(u8),
    /// `serde_json::Value`: user data, shape and keys stay as sent.
    Json,
    /// A byte vector behind `serde_bytes`: a CBOR byte string on the wire.
    Bytes,
    Named(u16),
    Opt(&'static Ty),
    Seq(&'static Ty),
    Map(&'static Ty),
    Tuple(&'static [Ty]),
}

pub(crate) const REQUIRED: u8 = 1;
/// An absent `Option` is still sent as `null` (the server may demand the key).
pub(crate) const NULL_WHEN_ABSENT: u8 = 2;
/// `null` is a value here ("clear", or a present JSON null), not an absence.
pub(crate) const KEEP_NULL: u8 = 4;

pub(crate) struct Field {
    pub name: &'static str,
    pub ty: Ty,
    pub flags: u8,
}

pub(crate) enum Shape {
    Unit,
    Newtype(Ty),
    Struct(&'static [Field]),
}

pub(crate) enum Def {
    Struct {
        fields: &'static [Field],
        deny_unknown: bool,
    },
    Enum {
        /// serde `tag = ".."`: internally (or, with `content`, adjacently) tagged.
        tag: Option<&'static str>,
        content: Option<&'static str>,
        /// Externally tagged enum with data: a payload family a body variant may wrap.
        routing: bool,
        deny_unknown: bool,
        variants: &'static [(&'static str, Shape)],
    },
}

include!(concat!(env!("OUT_DIR"), "/wire_schema.rs"));
